events { worker_connections 1024; }
http {
  upstream backend { server 122.128.18.238:3000; }
  server {
    listen 80; server_name tssb.local;
    return 301 https://$host$request_uri;
  }
  server {
    listen 443 ssl;
    server_name tssb.local;
    ssl_certificate /etc/ssl/certs/tssb.pem;
    location / { proxy_pass http://backend; }
  }
}

